import{createProject,validateProject}from'./project.js?v=0.6.0';
export function factoryPatch(entry,audio,rate){const patch=createProject();patch.name=entry.name;patch.sampleName=entry.source;patch.rate=rate;patch.loopEnd=rate*16;patch.sample=audio;Object.assign(patch.params,entry.params);return validateProject(patch);}
export async function fetchFactorySound(entry,client,decode){const result=await client.api('prepare',{asset_id:entry.asset_id,start:0,duration:entry.duration,expected_fingerprint:entry.fingerprint});if(result.fingerprint!==entry.fingerprint||result.asset?.filename!==entry.source)throw Error('Factory source differs from this Zogg library. Current sound preserved.');const bytes=await client.audio(result.audio),decoded=await decode(bytes);if(decoded.duration>2.01||decoded.length<2)throw Error('Invalid factory audio length');const audio=[decoded.getChannelData(0).slice(),decoded.getChannelData(Math.min(1,decoded.numberOfChannels-1)).slice()];return factoryPatch(entry,audio,decoded.sampleRate);}
